#include <algorithm>
#include <cmath>
#include <fstream>
#include <iostream>
#include <map>
#include <stdexcept>
#include <utility>
namespace sima {
namespace {
Image auto_mask(const Image&g){Image m{g.width,g.height,1,std::vector<std::uint8_t>(g.pixels.size())};long sum=0;std::size_t n=0;for(int x=0;x<g.width;++x){sum+=g.at(x,0)+g.at(x,g.height-1);n+=2;}for(int y=1;y<g.height-1;++y){sum+=g.at(0,y)+g.at(g.width-1,y);n+=2;}int bg=static_cast<int>(sum/static_cast<long>(std::max<std::size_t>(n,1))),t=std::clamp(255-bg+24,18,55);for(int y=0;y<g.height;++y)for(int x=0;x<g.width;++x)if(std::abs(static_cast<int>(g.at(x,y))-bg)>t)m.at(x,y)=255;return m;}
Image normalize(Image mask,int size){int ax=mask.width,ay=mask.height,bx=-1,by=-1;for(int y=0;y<mask.height;++y)for(int x=0;x<mask.width;++x)if(mask.at(x,y)>127){ax=std::min(ax,x);ay=std::min(ay,y);bx=std::max(bx,x);by=std::max(by,y);}if(bx<ax||by<ay)throw std::runtime_error("No foreground; supply a mask with --masks");int w=bx-ax+1,h=by-ay+1;Image crop{w,h,1,std::vector<std::uint8_t>(static_cast<std::size_t>(w)*h)};for(int y=0;y<h;++y)for(int x=0;x<w;++x)crop.at(x,y)=mask.at(x+ax,y+ay);double sc=size*.78/std::max(w,h);int rw=std::max(1,static_cast<int>(std::round(w*sc))),rh=std::max(1,static_cast<int>(std::round(h*sc)));auto r=resize_image(crop,rw,rh);Image out{size,size,1,std::vector<std::uint8_t>(static_cast<std::size_t>(size)*size)};int ox=(size-rw)/2,oy=(size-rh)/2;for(int y=0;y<rh;++y)for(int x=0;x<rw;++x)out.at(x+ox,y+oy)=r.at(x,y)>127?255:0;return out;}
}
TrainReport train_dataset(const TrainOptions&o){if(o.canvas_size<32||o.canvas_size>2048)throw std::runtime_error("Canvas size must be 32..2048");auto items=scan_dataset(o.input,o.masks);if(o.limit&&items.size()>o.limit)items.resize(o.limit);TrainReport rep{items.size(),0,0};std::map<std::string,std::size_t> shape_counts;auto dir=o.output/o.category;std::filesystem::create_directories(dir/"images");std::filesystem::create_directories(dir/"definitions");std::ofstream csv(dir/"training_manifest.csv");csv<<"source,status,primitive,confidence\n";std::size_t i=0;for(auto&it:items){++i;try{auto gray=to_grayscale(load_image(it.image,1));Image mask;if(!it.mask.empty()){mask=load_image(it.mask,1);mask=resize_image(mask,gray.width,gray.height);const auto max_value=*std::max_element(mask.pixels.begin(),mask.pixels.end());const auto min_value=*std::min_element(mask.pixels.begin(),mask.pixels.end());const bool trimap=min_value>=1&&max_value<=3;for(auto&v:mask.pixels)v=trimap?(v==2?0:255):(v>127?255:0);}else mask=auto_mask(gray);mask=normalize(std::move(mask),o.canvas_size);auto pts=boundary_points(mask,1600);if(pts.size()<3)throw std::runtime_error("Insufficient contour points");pts=simplify_contour(convex_hull(pts),2.0);auto match=classify_shape(pts);auto b=bounds_of(pts);Document d;d.name=o.category;d.canvas_width=o.canvas_size;d.canvas_height=o.canvas_size;Shape s;s.type=match.type;s.component="silhouette";s.x=b.x/o.canvas_size;s.y=b.y/o.canvas_size;s.width=b.width/o.canvas_size;s.height=b.height/o.canvas_size;for(auto p:pts)s.points.push_back({p.x/o.canvas_size,p.y/o.canvas_size});d.shapes.push_back(s);auto stem=o.category+"-"+(i<10000?std::string(4-std::to_string(i).size(),'0'):"")+std::to_string(i);save_png(dir/"images"/(stem+"trained.png"),mask);save_sdf(dir/"definitions"/(stem+".sdf"),d);csv<<it.image.filename().string()<<",trained,"<<match.type<<','<<match.confidence<<'\n';++rep.trained;++shape_counts[match.type];std::cout<<"[trained] "<<it.image.filename()<<" -> "<<match.type<<'\n';}catch(const std::exception&e){csv<<it.image.filename().string()<<",skipped,,"<<e.what()<<'\n';++rep.skipped;std::cerr<<"[skip] "<<it.image<<": "<<e.what()<<'\n';}}std::ofstream k(dir/"knowledge.txt");k<<"SIMA_KNOWLEDGE 1\ncategory "<<o.category<<"\ntrained "<<rep.trained<<"\nskipped "<<rep.skipped<<"\n";k<<"scope silhouette-only; semantic landmarks are not inferred in v0.1\n";for(const auto&[type,count]:shape_counts)k<<"primitive "<<type<<" "<<count<<" "<<static_cast<double>(count)/static_cast<double>(std::max<std::size_t>(rep.trained,1))<<"\n";return rep;}
}
